package tw.radar.shortscan;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.time.*;import java.util.*;
public class PublicScannerTest {
 @Test public void datesAndNumbers(){assertEquals(LocalDate.of(2026,11,25),PublicScanner.date("115/11/25"));assertEquals(LocalDate.of(2026,11,25),PublicScanner.date("20261125"));assertNull(PublicScanner.num("--"));assertNull(PublicScanner.num("NaN"));assertEquals(1000.0,PublicScanner.num("1,000"),0);}
 @Test public void allRequiredAndMissing(){JSONObject a=new JSONObject(),b=new JSONObject(),c=new JSONObject();for(JSONObject x:Arrays.asList(a,b,c)){PublicScanner.put(x,"market","TWSE");PublicScanner.put(x,"foreign",4.9);}PublicScanner.put(a,"short_delta",1);PublicScanner.put(b,"short_delta",0);JSONObject result=PublicScanner.screen(Arrays.asList(a,b,c),new JSONArray(Arrays.asList("foreign5","short_up")));assertEquals(1,result.optInt("matched"));assertEquals(1,result.optInt("failed"));assertEquals(1,result.optInt("unknown"));assertEquals(1,result.optJSONObject("missing").optInt("short_up"));}
 @Test public void strictForeignThreshold(){JSONObject a=new JSONObject();PublicScanner.put(a,"foreign",5);assertFalse(PublicScanner.states(a).optBoolean("foreign5"));assertTrue(PublicScanner.states(a).optBoolean("foreign10"));assertTrue(PublicScanner.states(a).isNull("big_down"));}
 @Test public void marginAndVolume(){JSONObject m=PublicScanner.margin(100.0,90.0,5.0,9.0);assertEquals(-10,m.optDouble("margin_delta"),0);assertEquals(4,m.optDouble("short_delta"),0);JSONObject q=new JSONObject();PublicScanner.put(q,"TradeVolume","501000");PublicScanner.put(q,"ClosingPrice","97");PublicScanner.put(q,"Change","-3");assertEquals(501,PublicScanner.quote(q).optDouble("lots"),0);assertEquals(-3,PublicScanner.quote(q).optDouble("change_pct"),0);}
 @Test public void completeTiersOnly(){double[] a=new double[15];a[0]=10;a[1]=20;a[2]=20;a[11]=10;a[14]=40;assertArrayEquals(new double[]{50,50},PublicScanner.sums(a),0);a[4]=Double.NaN;assertNull(PublicScanner.sums(a));}
 @Test public void historicalDates(){assertFalse(PublicScanner.fresh(LocalDate.of(2026,11,15),LocalDate.of(2026,11,25),7));assertFalse(PublicScanner.fresh(LocalDate.of(2026,11,26),LocalDate.of(2026,11,25),7));}
}